beforeExample:
class TestClass {
    String getContent() { return "content"; }
    void foo() {
        StringBuffer buffer = new StringBuffer(getContent());
        buffer.append("more");
        System.out.println(buffer.toString());
    }
}

afterExample:
class TestClass {
    String getContent() { return "content"; }
    void foo() {
        StringBuilder buffer = new StringBuilder(getContent());
        buffer.append("more");
        System.out.println(buffer.toString());
    }
}

negativeExample:
class NegativeTestClass {
    private StringBuffer fieldBuffer = new StringBuffer("initial"); // Should not match: field, not a local variable assignment
    String getContent() { return "content"; }
    void foo() {
        fieldBuffer.append(getContent());
        System.out.println(fieldBuffer.toString());
    }
}
